const eq = (actual, expected) => {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`Expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
};
const throws = (fn, name) => { try { fn(); } catch (error) { eq(error.name, name); return; } throw new Error(`Expected ${name}`); };
const reject = async (promise, name) => { try { await promise; } catch (error) { eq(error.name, name); return; } throw new Error(`Expected ${name}`); };
const encoder = new TextEncoder();
