eq(/^........-....-4...-[89ab]...-............$/.test(crypto.randomUUID()), true);
throws(() => crypto.getRandomValues(new Float32Array(1)), 'TypeMismatchError');
throws(() => crypto.getRandomValues(new Uint8Array(65537)), 'QuotaExceededError');
const hex = buffer => Array.from(new Uint8Array(buffer), x => x.toString(16).padStart(2,'0')).join('');
eq(hex(await crypto.subtle.digest('sha-256', encoder.encode('abc'))), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
eq(hex(await crypto.subtle.digest('SHA-384', new Uint8Array())), '38b060a751ac96384cd9327eb1b1e36a21fdb71114be07434c0cc7bf63f6e1da274edebfe76f65fbd51ad2f14898b95b');
