let pulls = 0, cancelled;
const stream = new ReadableStream({ pull(c) { pulls++; c.enqueue(pulls); }, cancel(reason) { cancelled = reason; } }, {highWaterMark:0});
await Promise.resolve(); eq(pulls,0);
const reader = stream.getReader(); eq(stream.locked,true); await reject(stream.cancel(), 'TypeError');
eq(await reader.read(), {value:1,done:false}); eq(pulls,1); await reader.cancel('stop'); eq(cancelled,'stop'); reader.releaseLock();
let release; const writes = [];
const writable = new WritableStream({ write(value) { writes.push(value); return new Promise(r => release = r); } });
const writer = writable.getWriter(); const writing = writer.write(7); eq(writer.desiredSize,0);
await Promise.resolve(); release(); await writing; await writer.ready; eq(writes,[7]); await writer.close();
const doubled = [];
await new ReadableStream({start(c){c.enqueue(2);c.enqueue(3);c.close();}})
  .pipeThrough(new TransformStream({transform(v,c){c.enqueue(v*2);}}))
  .pipeTo(new WritableStream({write(v){doubled.push(v);}}));
eq(doubled,[4,6]);
const controller = new AbortController(); let cancelReason, abortReason;
const piping = new ReadableStream({cancel(r){cancelReason=r;}}).pipeTo(new WritableStream({abort(r){abortReason=r;}}),{signal:controller.signal});
controller.abort(new Error('halt')); await reject(piping, 'Error'); eq(cancelReason.message,'halt'); eq(abortReason.message,'halt');
